"""The `sapn_interval` parser (D3 §5, §5.2, §13). Every file is generated by `make_nem12` or edited from its output."""

import json
from datetime import date, datetime, timedelta

import pytest

from energatron.adapters.sources.sapn_nem12 import SAPN_INTERVAL, SapnIntervalParser
from energatron.core.errors import InvalidInputError
from energatron.core.models.catalog import Coverage, SourceInfo, SourceType
from energatron.ports.sources import SourceParser
from tests.fixtures.make_nem12 import Nem12Spec, QualityRange, make_nem12, nem12_header_dt, sapn_filename
from tests.fixtures.synthetic import SYNTHETIC_NMI, SYNTHETIC_NMI11, SYNTHETIC_SERIAL

START = date(2025, 1, 1)
GENERATED = datetime(2025, 1, 20, 10, 3, 45)
WINDOW = (date(2024, 12, 31), date(2025, 1, 20))
NAME = sapn_filename("DETAILED", SYNTHETIC_NMI, WINDOW, GENERATED)
RENAMED = "meter-data.csv"


def nem12(**kw: object) -> bytes:
    spec_kw: dict[str, object] = {"start": START, "days": 4}
    spec_kw.update(kw)
    return make_nem12(Nem12Spec(**spec_kw))  # type: ignore[arg-type]


def inspect(data: bytes, filename: str = NAME) -> SourceInfo:
    return SAPN_INTERVAL.inspect(filename, data)


def reason(data: bytes, filename: str = NAME) -> str:
    with pytest.raises(InvalidInputError) as caught:
        inspect(data, filename)
    value = caught.value.details["reason"]
    assert isinstance(value, str)
    return value


def edit(data: bytes, old: str, new: str, count: int = 1) -> bytes:
    text = data.decode("utf-8")
    assert old in text
    return text.replace(old, new, count).encode("utf-8")


def lines(data: bytes) -> list[str]:
    return data.decode("utf-8").split("\n")


def join(rows: list[str]) -> bytes:
    return "\n".join(rows).encode("utf-8")


# --- the parser itself ----------------------------------------------------------------------------------------------


def test_the_parser_is_a_source_parser_for_sapn_interval_version_1() -> None:
    parser: SourceParser = SAPN_INTERVAL
    assert isinstance(SAPN_INTERVAL, SapnIntervalParser)
    assert parser.source is SourceType.SAPN_INTERVAL
    assert parser.version == 1


# --- detect ---------------------------------------------------------------------------------------------------------


def test_detect_filename_and_content() -> None:
    detection = SAPN_INTERVAL.detect(NAME, nem12())
    assert detection is not None
    assert detection.source is SourceType.SAPN_INTERVAL
    assert detection.evidence == ("filename", "content")


def test_detect_content_only_from_a_200_or_a_100() -> None:
    for data in (nem12(), nem12(header_100=True)):
        detection = SAPN_INTERVAL.detect(RENAMED, data)
        assert detection is not None and detection.evidence == ("content",)


def test_detect_filename_only() -> None:
    detection = SAPN_INTERVAL.detect(NAME, b"Account Code,Read Datetime\r\n")
    assert detection is not None and detection.evidence == ("filename",)


def test_detect_neither() -> None:
    assert SAPN_INTERVAL.detect(RENAMED, b"Description,Date,Amount\r\n") is None
    assert SAPN_INTERVAL.detect(RENAMED, b"") is None
    assert SAPN_INTERVAL.detect(RENAMED, b"\xff\xfe\x00garbage") is None


def test_the_filename_extension_is_case_insensitive_and_the_rest_is_not() -> None:
    assert SAPN_INTERVAL.detect(NAME.replace(".csv", ".CSV"), b"x") is not None
    assert SAPN_INTERVAL.detect(NAME.replace("DETAILED", "detailed"), b"x") is None
    assert SAPN_INTERVAL.detect(NAME.replace(".csv", ".txt"), b"x") is None
    summary = sapn_filename("SUMMARY", SYNTHETIC_NMI, WINDOW, GENERATED)
    assert SAPN_INTERVAL.detect(summary, b"x") is None


@pytest.mark.parametrize("interval", ["5", "05", "15", "30"])
def test_detect_accepts_a_200_with_a_known_interval_and_kwh_in_any_case(interval: str) -> None:
    header = f"200,{SYNTHETIC_NMI},E1,1,E1,E1,{SYNTHETIC_SERIAL},kWh,{interval},\n".encode()
    detection = SAPN_INTERVAL.detect(RENAMED, header)
    assert detection is not None and detection.evidence == ("content",)


@pytest.mark.parametrize(
    "first",
    [
        f"200,{SYNTHETIC_NMI},E1,1,E1,E1,{SYNTHETIC_SERIAL},KWH,10,",  # unknown interval
        f"200,{SYNTHETIC_NMI},E1,1,E1,E1,{SYNTHETIC_SERIAL},MWH,5,",  # another unit
        f"200,{SYNTHETIC_NMI},E1,1,E1,E1,{SYNTHETIC_SERIAL},KWH,5",  # 9 fields
        "100,NEM13,202501010000,A,B",  # another format
        "300,20250101,0.1",
    ],
)
def test_detect_rejects_other_first_lines(first: str) -> None:
    assert SAPN_INTERVAL.detect(RENAMED, f"{first}\n".encode()) is None


def test_detect_skips_leading_blank_lines_and_a_bom_and_takes_crlf() -> None:
    data = b"\xef\xbb\xbf\r\n\r\n" + nem12(line_ending="\r\n")
    detection = SAPN_INTERVAL.detect(RENAMED, data)
    assert detection is not None and detection.evidence == ("content",)


def test_detect_needs_only_the_first_64_kib() -> None:
    data = nem12(days=200)
    assert len(data) > 64 * 1024
    detection = SAPN_INTERVAL.detect(NAME, data[: 64 * 1024])
    assert detection is not None and detection.evidence == ("filename", "content")


# --- inspect: the SourceInfo ----------------------------------------------------------------------------------------


def test_inspect_a_default_file() -> None:
    info = inspect(nem12(days=4))
    assert info.source_ts == GENERATED
    assert info.source_ts.tzinfo is None
    assert info.coverage == Coverage(start=START, end=START + timedelta(days=3))
    assert info.extension == ".csv"
    assert info.extra == {
        "interval_minutes": 5,
        "nmi_suffixes": ["E1"],
        "uom": "KWH",
        "days": 4,
        "days_v": 0,
        "header_records": 1,
        "requested_window": {"start": "2024-12-31", "end": "2025-01-20"},
        "source_ts_from": "filename",
    }
    assert info.identifiers == {"nmi": [SYNTHETIC_NMI, SYNTHETIC_NMI11], "meter_serial": [SYNTHETIC_SERIAL]}


def test_extra_never_holds_an_identifier() -> None:
    info = inspect(nem12(suffixes=("E1", "B1"), header_100=True))
    text = json.dumps(info.extra)
    for value in (SYNTHETIC_NMI, SYNTHETIC_NMI11, SYNTHETIC_SERIAL, NAME, "20250120100345"):
        assert value not in text


def test_no_100_record_is_fine() -> None:
    assert lines(nem12())[0].startswith("200,")
    assert inspect(nem12()).extra["header_records"] == 1


def test_a_100_record_first_is_fine_and_a_renamed_file_takes_source_ts_from_it() -> None:
    spec = Nem12Spec(start=START, days=3, header_100=True)
    data = make_nem12(spec)
    assert inspect(data).source_ts == GENERATED  # the filename wins
    info = inspect(data, RENAMED)
    assert info.source_ts == nem12_header_dt(spec)
    assert info.extra["source_ts_from"] == "nem12_header"
    assert info.extra["requested_window"] is None
    assert info.identifiers["nmi"] == [SYNTHETIC_NMI]


def test_a_renamed_file_without_a_100_takes_the_latest_update_time() -> None:
    def update(day: date) -> datetime:
        return datetime(2025, 3, 1, 7, 8, 9) if day == START + timedelta(days=1) else datetime(2025, 2, 1, 5, 0, 0)

    info = inspect(nem12(update_dt=update), RENAMED)
    assert info.source_ts == datetime(2025, 3, 1, 7, 8, 9)
    assert info.extra["source_ts_from"] == "content"


def test_repeated_200s_with_blank_lines_are_counted() -> None:
    data = nem12(days=10, repeat_200_every=3)
    assert "" in lines(data)
    info = inspect(data)
    assert info.extra["header_records"] == 4
    assert info.extra["days"] == 10


def test_v_days_with_400s() -> None:
    v_days = {
        START: (QualityRange(1, 100, "A"), QualityRange(101, 288, "S14", "51")),
        START + timedelta(days=2): (
            QualityRange(
                1,
                288,
                "F17",
                "79",
            ),
        ),
    }
    info = inspect(nem12(v_days=v_days))
    assert info.extra["days_v"] == 2
    assert info.extra["days"] == 4


def test_a_400_after_an_a_day_is_rejected() -> None:
    rows = lines(nem12())
    rows.insert(2, "400,1,288,E52,51,")
    assert reason(join(rows)) == "unexpected_400"


@pytest.mark.parametrize(("start", "end"), [("0", "10"), ("1", "289"), ("20", "10"), ("x", "10")])
def test_a_400_outside_the_day_is_rejected(start: str, end: str) -> None:
    data = nem12(v_days={START: (QualityRange(1, 288, "E52"),)})
    assert reason(edit(data, "400,1,288,", f"400,{start},{end},")) == "bad_quality_range"


@pytest.mark.parametrize("minutes", [5, 15, 30])
def test_5_15_and_30_minute_files(minutes: int) -> None:
    data = nem12(interval_minutes=minutes, v_days={START: (QualityRange(1, 1440 // minutes, "E52"),)})
    info = inspect(data)
    assert info.extra["interval_minutes"] == minutes
    rows = [row.split(",") for row in lines(data) if row.startswith("300,")]
    assert all(len(row) == 2 + 1440 // minutes + 5 for row in rows)


def test_a_mixed_interval_file_is_rejected() -> None:
    five = nem12(days=2)
    thirty = nem12(start=START + timedelta(days=2), days=2, interval_minutes=30)
    rows = lines(five)[:-2] + lines(thirty)
    assert reason(join(rows)) == "mixed_interval"


def test_an_unsupported_interval_is_rejected() -> None:
    assert reason(edit(nem12(), ",KWH,5,", ",KWH,10,")) == "bad_interval"


def test_a_unit_other_than_kwh_is_rejected() -> None:
    assert reason(edit(nem12(), ",KWH,", ",MWH,")) == "bad_unit"
    assert inspect(edit(nem12(), ",KWH,", ",kWh,")).extra["uom"] == "KWH"


def test_a_short_200_is_rejected() -> None:
    assert reason(edit(nem12(), ",KWH,5,", ",KWH,5")) == "bad_200"


def test_crlf_and_a_bom_are_accepted() -> None:
    data = b"\xef\xbb\xbf" + nem12(line_ending="\r\n", header_100=True)
    info = inspect(data)
    assert info.extra["days"] == 4
    assert info.coverage == Coverage(start=START, end=START + timedelta(days=3))


def test_two_suffixes_count_each_date_once() -> None:
    info = inspect(nem12(suffixes=("E1", "B1")))
    assert info.extra["nmi_suffixes"] == ["B1", "E1"]
    assert info.extra["days"] == 4
    assert info.extra["header_records"] == 2


def test_coverage_is_from_the_300_dates_over_all_suffixes() -> None:
    late = nem12(start=START + timedelta(days=5), days=2, suffixes=("B1",))
    rows = lines(nem12(days=3))[:-2] + lines(late)
    info = inspect(join(rows))
    assert info.coverage == Coverage(start=START, end=START + timedelta(days=6))
    assert info.extra["days"] == 5


def test_identifiers_take_every_serial_but_not_empty_ones() -> None:
    data = edit(nem12(), f",{SYNTHETIC_SERIAL},", ",,")
    assert inspect(data).identifiers == {"nmi": [SYNTHETIC_NMI, SYNTHETIC_NMI11], "meter_serial": []}
    other = nem12(start=START + timedelta(days=4), meter_serial="SYN0000002")
    both = join(lines(nem12())[:-2] + lines(other))
    assert inspect(both).identifiers["meter_serial"] == [SYNTHETIC_SERIAL, "SYN0000002"]


def test_an_identifier_never_reaches_an_error() -> None:
    bad = nem12(trailer_900=False)
    with pytest.raises(InvalidInputError) as caught:
        inspect(bad)
    text = caught.value.message + json.dumps(caught.value.details)
    assert SYNTHETIC_NMI not in text and SYNTHETIC_SERIAL not in text and NAME not in text


# --- inspect: malformed variants ------------------------------------------------------------------------------------


def test_a_missing_900_is_truncated() -> None:
    assert reason(nem12(trailer_900=False)) == "truncated"
    cut = nem12()[: len(nem12()) // 2]
    assert reason(cut.rsplit(b"\n", 1)[0] + b"\n") == "truncated"


def test_a_record_after_the_900_is_rejected() -> None:
    rows = lines(nem12())
    rows.insert(-1, "900")
    assert reason(join(rows)) == "misplaced_900"


def test_an_unknown_record_type_is_rejected() -> None:
    rows = lines(nem12())
    rows.insert(2, "250,whatever")
    assert reason(join(rows)) == "unknown_record"


def test_a_100_elsewhere_is_a_bad_header() -> None:
    rows = lines(nem12(header_100=True))
    rows.insert(3, rows[0])
    assert reason(join(rows)) == "bad_header"


@pytest.mark.parametrize("stamp", ["2025012010", "202501201003", "202513011200", "202501202500", "20250120100345"])
def test_a_100_datetime_must_be_12_digits_and_a_valid_time(stamp: str) -> None:
    data = nem12(header_100=True)
    header = lines(data)[0].split(",")
    header[2] = stamp
    rows = [",".join(header), *lines(data)[1:]]
    if stamp == "202501201003":
        assert inspect(join(rows)).extra["days"] == 4
    else:
        assert reason(join(rows)) == "bad_header"


def test_a_300_before_any_200_is_rejected() -> None:
    rows = lines(nem12())
    assert reason(join(rows[1:])) == "orphan_300"


@pytest.mark.parametrize("change", [-1, 1])
def test_a_300_one_field_short_or_long(change: int) -> None:
    rows = lines(nem12())
    fields = rows[1].split(",")
    fields = fields[:-1] if change < 0 else [*fields, ""]
    rows[1] = ",".join(fields)
    assert reason(join(rows)) == "bad_field_count"


@pytest.mark.parametrize("day", ["20250230", "2025010", "2025-01-01", "abcdefgh"])
def test_a_300_with_a_bad_date(day: str) -> None:
    assert reason(edit(nem12(), "300,20250101,", f"300,{day},")) == "bad_date"


@pytest.mark.parametrize("stamp", ["", "2025010205000", "20250102250000"])
def test_a_300_with_a_missing_or_bad_update_time(stamp: str) -> None:
    assert reason(edit(nem12(), ",20250102050000,", f",{stamp},")) == "bad_update_time"


def test_a_duplicate_day_is_rejected() -> None:
    rows = lines(nem12())
    rows.insert(2, rows[1])
    assert reason(join(rows)) == "duplicate_day"


def test_the_same_day_under_another_suffix_is_not_a_duplicate() -> None:
    assert inspect(nem12(suffixes=("E1", "E2"))).extra["days"] == 4


def test_a_file_without_300s_is_rejected() -> None:
    rows = [row for row in lines(nem12()) if not row.startswith("300,")]
    assert reason(join(rows)) == "no_data"


def test_bytes_that_are_not_utf8_are_rejected() -> None:
    assert reason(nem12() + b"\xff\n900\n") == "not_utf8"


@pytest.mark.parametrize(
    "name",
    [
        f"{SYNTHETIC_NMI11}_20241332_20250120_20250120100345_SAPN_DETAILED.csv",  # bad from
        f"{SYNTHETIC_NMI11}_20241231_20250231_20250120100345_SAPN_DETAILED.csv",  # bad to
        f"{SYNTHETIC_NMI11}_20241231_20250120_20250120250000_SAPN_DETAILED.csv",  # bad gen
    ],
)
def test_a_bad_filename_date_is_bad_filename(name: str) -> None:
    assert reason(nem12(), name) == "bad_filename"


# --- inspect: the order of the checks (D3 §5.2) ---------------------------------------------------------------------

BAD_NAME = f"{SYNTHETIC_NMI11}_20241231_20250120_20250120250000_SAPN_DETAILED.csv"


def test_the_record_checks_come_before_the_filename_check() -> None:
    assert reason(nem12(trailer_900=False), BAD_NAME) == "truncated"
    rows = lines(nem12())
    rows.insert(2, rows[1])
    assert reason(join(rows), BAD_NAME) == "duplicate_day"


def test_the_record_checks_come_before_the_100_datetime_check() -> None:
    rows = lines(nem12(header_100=True))
    header = rows[0].split(",")
    header[2] = "202513011200"
    rows[0] = ",".join(header)
    rows.insert(3, rows[2])  # a duplicate day after the bad header
    assert reason(join(rows)) == "duplicate_day"
    assert reason(join(rows[:3] + rows[4:])) == "bad_header"


def test_the_100_datetime_check_comes_before_the_filename_check() -> None:
    rows = lines(nem12(header_100=True))
    header = rows[0].split(",")
    header[2] = "202513011200"
    rows[0] = ",".join(header)
    assert reason(join(rows), BAD_NAME) == "bad_header"
